// @category GFZ
import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.*;import ghidra.program.model.symbol.*;import ghidra.program.model.address.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class DumpUnresolvedNeighborhoodDomains extends GhidraScript{
 static boolean pref(Function f,String p){for(FunctionTag t:f.getTags())if(t.getName().startsWith(p))return true;return false;}static boolean tag(Function f,String n){for(FunctionTag t:f.getTags())if(t.getName().equals(n))return true;return false;}
 static String cls(Function f){ArrayList<String>a=new ArrayList<>();for(FunctionTag t:f.getTags()){String n=t.getName();if(n.startsWith("GFZ.V120.PrimaryOwner."))a.add("OWNER:"+n.substring(22));else if(n.equals("GFZ.V120.FinalNoPrimaryOwner"))a.add("FINALNO");else if(n.startsWith("GFZ.V121.CodeDomain."))a.add("DOMAIN:"+n.substring(20));}Collections.sort(a);return String.join(",",a);}
 static String esc(String s){return s==null?"":s.replace("\\","\\\\").replace("\t","\\t").replace("\n","\\n").replace("\r","\\r");}
 public void run()throws Exception{String[]a=getScriptArgs();if(a.length!=1)throw new IllegalArgumentException("out");FunctionManager fm=currentProgram.getFunctionManager();ReferenceManager rm=currentProgram.getReferenceManager();Listing li=currentProgram.getListing();int n=0;try(PrintWriter w=new PrintWriter(new OutputStreamWriter(new FileOutputStream(a[0]),StandardCharsets.UTF_8))){w.println("entry\tname\tbody_bytes\tinsns\tcallers\tcallees");for(Function f:fm.getFunctions(true)){if(f.isExternal()||pref(f,"GFZ.V120.PrimaryOwner.")||tag(f,"GFZ.V120.FinalNoPrimaryOwner")||pref(f,"GFZ.V121.CodeDomain."))continue;int ic=0;for(InstructionIterator ii=li.getInstructions(f.getBody(),true);ii.hasNext();){ii.next();ic++;}TreeSet<String> callers=new TreeSet<>();ReferenceIterator ri=rm.getReferencesTo(f.getEntryPoint());while(ri.hasNext()){Reference r=ri.next();Function cf=fm.getFunctionContaining(r.getFromAddress());if(cf!=null&&!cf.isExternal())callers.add(String.format("%08X[%s]{%s}",cf.getEntryPoint().getOffset(),cf.getName(),cls(cf)));}TreeSet<String> callees=new TreeSet<>();for(Function g:f.getCalledFunctions(monitor))callees.add(String.format("%08X[%s]{%s}",g.getEntryPoint().getOffset(),g.getName(),cls(g)));w.printf("%08X\t%s\t%d\t%d\t%s\t%s%n",f.getEntryPoint().getOffset(),esc(f.getName()),f.getBody().getNumAddresses(),ic,esc(String.join(";",callers)),esc(String.join(";",callees)));n++;}}println("UNRESOLVED_NEIGHBORHOOD_DOMAINS_PASS total="+n);}
}
